pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ACCURAL_DEPOSIT} from "../src/ACCURAL_DEPOSIT.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ACCURAL_DEPOSIT c;

    function setUp() public {
        c = new ACCURAL_DEPOSIT();
    }

    function _run(uint256 d, uint256 a) internal {
        d = bound(d, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        d = bound(d, 0, 1);
        vm.assume(d > 0 && a > 0 && a <= d);
        uint256 balBefore;
        try c.balances(address(this)) returns (uint256 __r) { balBefore = __r; } catch { return; }
        try c.SetMinSum(d) {} catch { return; }
        try c.Deposit{value: d}() {} catch { return; }
        try c.Collect(a) {} catch { return; }
        assertTrue(c.balances(address(this)) == balBefore + d - a);
    }

    function testFuzz_run(uint256 d, uint256 a) public {
        _run(d, a);
    }

    receive() external payable {}
}
